#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // In-place LU factorization without pivoting (Doolittle-style storage):
    // - U is stored on and above the diagonal
    // - L is stored below the diagonal with implicit unit diagonal
    //
    // For each pivot k:
    //   1) Compute multipliers A[i,k] /= A[k,k] for i > k   (column update for L)
    //   2) Update trailing submatrix:
    //        A[i,j] -= A[i,k] * A[k,j]  for i,j > k
    //
    // Parallelization strategy:
    // - Step (1): parallel over rows i
    // - Step (2): parallel over rows i, inner loop over columns j
    //
    // This is correct for any thread count because:
    // - Each thread writes distinct A[i*N + k] entries in step (1)
    // - Each thread writes distinct trailing entries A[i*N + j] in step (2)
    // - The pivot row/column values read during each step are fully computed before use
    // - The implicit barrier at the end of each omp parallel for separates the phases

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute L entries below the pivot in column k.
        #pragma omp parallel for default(none) shared(A, N, k, pivot)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1;
             i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Update the trailing submatrix.
        #pragma omp parallel for default(none) shared(A, N, k)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1;
             i < static_cast<std::ptrdiff_t>(N); ++i) {
            const double lik = A[static_cast<size_t>(i) * N + k];
            const size_t row_i = static_cast<size_t>(i) * N;
            const size_t row_k = k * N;
            for (size_t j = k + 1; j < N; ++j) {
                A[row_i + j] -= lik * A[row_k + j];
            }
        }
    }
}
